SourceCode.Declaration:
/// <summary>
/// Parallel create-trans worker for ONE work unit and ONE transaction type.
/// A work unit is either a whole deal (<c>tableId</c> = TAMRebateDeal, for reconcile-by-deal) or a
/// single rebate table/line (<c>tableId</c> = TAMRebateTable, for reconcile-by-line). One task is
/// queued per unit so the batch scheduler load-balances at runtime — a heavy unit runs concurrently
/// with many light ones without needing to predict transaction volume up front.
/// Runs create-trans inline (maxBatchTaskNum = 1) so it never nests a further split. Posting is
/// deliberately NOT done here — it is a separate single-threaded task.
/// </summary>
internal final class METRebateCreateTask extends RunBaseBatch implements BatchRetryable
{
    private container recIds;
    private TableId tableId;
    private TAMRebateTransactionType rebateTransactionType;
    private TAMRebateFromDate fromDate;
    private TAMRebateToDate toDate;

    #DEFINE.CurrentVersion(2)

}

Method.Source:
internal static METRebateCreateTask construct(
    TAMRebateTransactionType _type,
    TableId _tableId,
    container _recIds,
    TAMRebateFromDate _f,
    TAMRebateToDate _t)
{
    METRebateCreateTask task = new METRebateCreateTask();
    task.rebateTransactionType = _type;
    task.tableId = _tableId;
    task.recIds = _recIds;
    task.fromDate = _f;
    task.toDate = _t;

    return task;
}

public void run()
{
    METRebateCombinedFlow::createTrans(rebateTransactionType, tableId, recIds, fromDate, toDate);
}

public container pack()
{
    return [#CurrentVersion, recIds, tableId, rebateTransactionType, fromDate, toDate];
}

public boolean unpack(container _p)
{
    Integer version = conPeek(_p, 1);
    if (version != #CurrentVersion)
    {
        return false;
    }

    [version, recIds, tableId, rebateTransactionType, fromDate, toDate] = _p;

    return true;
}

public ClassDescription caption()
{
    return strFmt("Rebate create transactions (%1) : %2 - %3", enum2str(rebateTransactionType), tableId == tableNum(TAMRebateDeal) ? 'Deal' : 'Deal line', conPeek(recIds, 1));
}

[Hookable(false)]
public final boolean isRetryable()
{
    return true;
}
